// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { pinchPanTransform, wheelTransform, MAX_GRAPH_ZOOM } from "../../../main/frontend/graph-explorer/graph-viewport.ts";
test("two fingers translate and scale the world point under their previous midpoint", () => {
  const current = { x: 30, y: -10, k: 2 };
  const result = pinchPanTransform(
    current,
    { distance: 100, midpoint: { x: 200, y: 100 } },
    { distance: 120, midpoint: { x: 250, y: 130 } },
  );
  assert.equal(result.k, 2.4);
  assert.ok(Math.abs(result.x + 85 * result.k - 250) < 1e-9);
  assert.ok(Math.abs(result.y + 55 * result.k - 130) < 1e-9);
});
test("parallel fingers pan even at the zoom limit; zero separation never produces NaN", () => {
  assert.deepEqual(
    pinchPanTransform(
      { x: 0, y: 0, k: MAX_GRAPH_ZOOM },
      { distance: 100, midpoint: { x: 100, y: 100 } },
      { distance: 200, midpoint: { x: 120, y: 130 } },
    ),
    { x: 20, y: 30, k: MAX_GRAPH_ZOOM },
  );
  assert.deepEqual(
    pinchPanTransform(
      { x: 0, y: 0, k: 1 },
      { distance: 0, midpoint: { x: 10, y: 10 } },
      { distance: 0, midpoint: { x: 30, y: 40 } },
    ),
    { x: 20, y: 30, k: 1 },
  );
});
test("pointer anchors account for the centered SVG viewBox at wide aspect ratios", async () => {
  const { clientPointToViewport } = await import("../../../main/frontend/graph-explorer/graph-viewport.ts");
  assert.deepEqual(
    clientPointToViewport(
      640,
      0,
      { left: 0, top: 0, width: 2560, height: 780 },
      { width: 1280, height: 780 },
    ),
    { x: 0, y: 0 },
  );
});
test("trackpad scroll pans at screen speed while pinch wheel events zoom about the cursor", () => {
  const view = { x: 20, y: 10, k: 1 },
    point = { x: 200, y: 150 };
  assert.deepEqual(
    wheelTransform(view, { deltaX: 25, deltaY: -50, deltaMode: 0 }, point, 0.5),
    { x: -30, y: 110, k: 1 },
  );
  const zoom = wheelTransform(
    view,
    { deltaX: 0, deltaY: -40, deltaMode: 0, ctrlKey: true },
    point,
    1,
  );
  assert.ok(zoom.k > 1);
  assert.ok(Math.abs(zoom.x + 180 * zoom.k - 200) < 1e-8);
  assert.ok(Math.abs(zoom.y + 140 * zoom.k - 150) < 1e-8);
  assert.deepEqual(
    wheelTransform(
      view,
      { deltaX: 0, deltaY: 2, deltaMode: 1, shiftKey: true },
      point,
      1,
    ),
    { x: -12, y: 10, k: 1 },
  );
});
